 "stem": "记 \\(\\triangle ABC\\) 的内角 \\(A,B,C\\) 的对边分别为 \\(a,b,c\\)。已知 \\(b^2=ac\\)，点 \\(D\\) 在边 \\(AC\\) 上，\\(BD\\sin\\angle ABC=a\\sin C\\)。（1）证明：\\(BD=b\\)；（2）若 \\(AD=2DC\\)，求 \\(\\cos\\angle ABC\\)。",
