 "sol": "(1) 由正弦定理 \\(\\dfrac{b}{\\sin\\angle ABC}=\\dfrac{c}{\\sin C}\\)，即 \\(\\sin\\angle ABC=\\dfrac{b\\sin C}{c}\\)。代入 \\(BD\\sin\\angle ABC=a\\sin C\\) 得 \\(BD\\cdot\\dfrac{b\\sin C}{c}=a\\sin C\\)，故 \\(BD\\cdot b=ac=b^2\\)，\\(BD=b\\)。(2) 由 \\(AD=2DC\\) 得 \\(\\overrightarrow{BD}=\\dfrac13\\overrightarrow{BA}+\\dfrac23\\overrightarrow{BC}\\)，平方并代入 \\(b^2=ac\\) 化简得 \\(6a^2-11ac+3c^2=0\\)，解得 \\(\\dfrac ac=3\\) 或 \\(\\dfrac13\\)。结合 \\(b^2=ac\\) 求 \\(\\cos\\angle ABC=\\dfrac{a^2+c^2-b^2}{2ac}\\)，舍去 \\(\\dfrac76\\)，得 \\(\\cos\\angle ABC=\\dfrac{7}{12}\\)。"
