 "sol": "(1) \\(f'(x)=1-\\ln x-1=-\\ln x\\)。\\(0<x<1\\) 时 \\(f'(x)>0\\)，\\(x>1\\) 时 \\(f'(x)<0\\)，故 \\(f(x)\\) 在 \\((0,1)\\) 单调递增，在 \\((1,+\\infty)\\) 单调递减。(2) 由 \\(b\\ln a-a\\ln b=a-b\\) 变形得 \\(\\dfrac{1+\\ln a}{a}=\\dfrac{1+\\ln b}{b}\\)，令 \\(u=\\dfrac1a,\\ v=\\dfrac1b\\)，则 \\(f(u)=f(v)\\)，不妨设 \\(0<u<1<v\\)。构造 \\(g(x)=f(x)-f(2-x)\\) 可证 \\(v>2-u\\)；构造 \\(h(x)=f(x)-f(e-x)\\) 可证 \\(v<e-u\\)，故 \\(2<u+v<e\\)，即 \\(2<\\dfrac1a+\\dfrac1b<e\\)。"
