 "sol": "(1)\\(a=2\\) 时 \\(f(x)=\\frac{x^{2}}{2^{x}}\\)，\\(f'(x)=\\frac{x\\cdot2^{x}(2-x\\ln2)}{4^{x}}\\)。令 \\(f'(x)=0\\) 得 \\(x=\\frac{2}{\\ln2}\\)。\\(0<x<\\frac{2}{\\ln2}\\) 时 \\(f'(x)>0\\)；\\(x>\\frac{2}{\\ln2}\\) 时 \\(f'(x)<0\\)。(2)\\(f(x)=1\\Leftrightarrow\\frac{\\ln x}{x}=\\frac{\\ln a}{a}\\)。设 \\(g(x)=\\frac{\\ln x}{x}\\)，\\(g'(x)=\\frac{1-\\ln x}{x^{2}}\\)，\\(g(x)\\) 在 \\((0,e)\\) 递增，\\((e,+\\infty)\\) 递减，\\(g(e)=\\frac{1}{e}\\) 为最大值，\\(g(1)=0\\)，\\(x\\to+\\infty\\) 时 \\(g(x)\\to0\\)。要有两个交点需 \\(0<\\frac{\\ln a}{a}<\\frac{1}{e}\\)，即 \\(0<g(a)<g(e)\\)，故 \\(a\\in(1,e)\\cup(e,+\\infty)\\)。"
