 "sol": "(1) 当 \\(MD\\perp x\\) 轴时，\\(M\\) 的横坐标为 \\(p\\)，\\(|MF|=p+\\dfrac{p}{2}=\\dfrac{3p}{2}=3\\)，故 \\(p=2\\)，抛物线方程为 \\(y^{2}=4x\\)。(2) 设 \\(l_{MN}:x=my+1\\ (m<0)\\)，联立 \\(y^{2}=4x\\) 得 \\(y_{1}+y_{2}=4m\\)，\\(y_{1}y_{2}=-4\\)。由 \\(M,D,A\\) 及 \\(N,D,B\\) 共线得 \\(y_{3}=\\dfrac{-8}{y_{1}},y_{4}=\\dfrac{-8}{y_{2}}\\)。于是 \\(\\tan\\beta=\\dfrac{1}{m}\\)，\\(\\tan\\alpha=\\dfrac{1}{2m}\\)，\\(\\tan(\\alpha-\\beta)=\\dfrac{-1}{2m+\\frac{1}{m}}\\)，当 \\(m=-\\dfrac{\\sqrt{2}}{2}\\) 时取最大。此时 \\(y_{3}+y_{4}=8m=-4\\sqrt{2}\\)，\\(y_{3}y_{4}=-16\\)，直线 \\(AB\\) 为 \\(4x+4\\sqrt{2}y-16=0\\)，即 \\(x+\\sqrt{2}y-4=0\\)。"
