 "sol": "(1) \\(f(-1)=0\\)，\\(f'(x)=3x^{2}-1\\)，\\(f'(-1)=2\\)，切线 \\(y=2x+2\\)。与 \\(g(x)\\) 切于 \\((x_{2},g(x_{2}))\\)，\\(g'(x)=2x\\)，\\(2x_{2}=2\\) 得 \\(x_{2}=1\\)，\\(g(1)=1+a=4\\)，故 \\(a=3\\)。(2) 切线方程为 \\(y=(3x_{1}^{2}-1)x-2x_{1}^{3}\\)，与 \\(g(x)\\) 相切得 \\(\\begin{cases}3x_{1}^{2}-1=2x_{2}\\\\ -2x_{1}^{3}=-x_{2}^{2}+a\\end{cases}\\)，消去 \\(x_{2}\\) 得 \\(a=\\dfrac{9}{4}x_{1}^{4}-2x_{1}^{3}-\\dfrac{3}{2}x_{1}^{2}+\\dfrac{1}{4}\\)。令 \\(h(x)=\\dfrac{9}{4}x^{4}-2x^{3}-\\dfrac{3}{2}x^{2}+\\dfrac{1}{4}\\)，\\(h'(x)=3x(3x+1)(x-1)\\)，求得 \\(h(x)\\) 值域为 \\([-1,+\\infty)\\)，故 \\(a\\) 的取值范围为 \\([-1,+\\infty)\\)。"
