 "sol": "(1) 当 \\(n=1\\) 时，\\(2S_{1}=a_{1}\\)，即 \\(a_{1}=0\\)。当 \\(n\\ge 2\\) 时，\\(2a_{n}=2S_{n}-2S_{n-1}=na_{n}-(n-1)a_{n-1}\\)，即 \\((n-2)a_{n}=(n-1)a_{n-1}\\)，故 \\(\\dfrac{a_{n}}{a_{n-1}}=\\dfrac{n-1}{n-2}\\)。累乘得 \\(a_{n}=1\\times\\dfrac{2}{1}\\times\\dfrac{3}{2}\\times\\cdots\\times\\dfrac{n-1}{n-2}=n-1\\)，\\(a_{1}=0\\) 也满足，故 \\(a_{n}=n-1\\)。(2) \\(\\dfrac{a_{n}+1}{2^{n}}=\\dfrac{n}{2^{n}}\\)，\\(T_{n}=\\dfrac{1}{2}+\\dfrac{2}{2^{2}}+\\cdots+\\dfrac{n}{2^{n}}\\)，\\(\\dfrac{1}{2}T_{n}=\\dfrac{1}{2^{2}}+\\dfrac{2}{2^{3}}+\\cdots+\\dfrac{n}{2^{n+1}}\\)，两式相减得 \\(\\dfrac{1}{2}T_{n}=\\dfrac{1}{2}+\\dfrac{1}{2^{2}}+\\cdots+\\dfrac{1}{2^{n}}-\\dfrac{n}{2^{n+1}}=1-\\dfrac{1}{2^{n}}-\\dfrac{n}{2^{n+1}}\\)，故 \\(T_{n}=2-(n+2)\\left(\\dfrac{1}{2}\\right)^{n}\\)。"
