 "ans": "(1) \\((\\ln2)x+y-\\ln2=0\\)；(2) 存在 \\(a=\\dfrac{1}{2}\\)，\\(b=-\\dfrac{1}{2}\\)；(3) \\(\\left(0,\\dfrac{1}{2}\\right)\\)。",
