 "sol": "定义域为 \\((0,2)\\)。（1）\\(b=0\\) 时 \\(f'(x)=\\dfrac{1}{x}+\\dfrac{1}{2-x}+a=\\dfrac{2}{x(2-x)}+a\\geq 0\\) 恒成立。\\(x=1\\) 时 \\(\\dfrac{2}{x(2-x)}\\) 取最小值 \\(2\\)，故 \\(a\\geq-2\\)。\\(a=-2\\) 时 \\(f'(x)=\\dfrac{2(x-1)^{2}}{x(2-x)}\\geq 0\\)，符合，故 \\(a_{\\min}=-2\\)。（2）\\(f(x)+f(2-x)=\\ln\\dfrac{x}{2-x}+ax+b(x-1)^{3}+\\ln\\dfrac{2-x}{x}+a(2-x)+b(1-x)^{3}=2a=2f(1)\\)，定义域关于 \\(x=1\\) 对称，故 \\(y=f(x)\\) 关于 \\((1,a)\\) 中心对称。（3）由条件知 \\(f(1)=-2\\) 即 \\(a=-2\\)。此时 \\(f'(x)=\\dfrac{(x-1)^{2}}{x(2-x)}[3bx(2-x)+2]\\)。当 \\(b\\geq-\\dfrac{2}{3}\\) 时 \\(f'(x)\\geq 0\\)，\\(f\\) 递增，\\(f(x)>-2=f(1)\\) 当且仅当 \\(1<x<2\\)；当 \\(b<-\\dfrac{2}{3}\\) 时存在 \\((0,1)\\) 内的极小值点使 \\(f(x)>-2\\) 在 \\((0,1)\\) 也成立，矛盾。故 \\(b\\in\\left[-\\dfrac{2}{3},+\\infty\\right)\\)。"
