 "sol": "（1）成绩不少于 \\(5\\) 分需甲第一阶段至少中 \\(1\\) 次且乙第二阶段至少中 \\(1\\) 次。\\(P=(1-0.6^{3})(1-0.5^{3})=(1-0.216)(1-0.125)=0.784\\times0.875=0.686\\)。（2）（i）甲先时得 \\(15\\) 分概率 \\(P_{甲}=[1-(1-p)^{3}]q^{3}\\)，乙先时 \\(P_{乙}=[1-(1-q)^{3}]p^{3}\\)。作差 \\(P_{甲}-P_{乙}=3pq(p-q)[(1-p)(1-q)-1]>0\\)（因 \\(0<p<q\\)），故 \\(P_{甲}>P_{乙}\\)，甲先。（ii）\\(E(X)=15[1-(1-p)^{3}]q=15(p^{3}-3p^{2}+3p)q\\)，\\(E(Y)=15(q^{3}-3q^{2}+3q)p\\)。作差 \\(E(X)-E(Y)=15(p-q)pq(p+q-3)>0\\)（因 \\(p+q<2<3\\)），故 \\(E(X)>E(Y)\\)，甲先。"
