 "diff": "未知",
 "stem": "已知双曲线 \\(C:x^{2}-y^{2}=m\\)（\\(m>0\\)），点 \\(P_{1}(5,4)\\) 在 \\(C\\) 上。\\(k\\) 为常数，\\(0<k<1\\)。依次构造点 \\(P_{n}(n=2,3,\\ldots)\\)：过 \\(P_{n-1}\\) 作斜率为 \\(k\\) 的直线与 \\(C\\) 的左支交于 \\(Q_{n-1}\\)，令 \\(P_{n}\\) 为 \\(Q_{n-1}\\) 关于 \\(y\\) 轴的对称点，记 \\(P_{n}(x_{n},y_{n})\\)。（1）若 \\(k=\\dfrac{1}{2}\\)，求 \\(x_{2},y_{2}\\)；（2）证明：\\(\\{x_{n}-y_{n}\\}\\) 是公比为 \\(\\dfrac{1+k}{1-k}\\) 的等比数列；（3）设 \\(S_{n}\\) 为 \\(\\triangle P_{n}P_{n+1}P_{n+2}\\) 的面积，证明：对任意正整数 \\(n\\)，\\(S_{n}=S_{n+1}\\)。",
 "opts": [
  "",
  "",
  "",
  ""
 ],
 "ans": "（1）\\(x_{2}=3,y_{2}=0\\)；（2）证明见解析；（3）证明见解析",
 "sol": "（1）\\(P_{1}(5,4)\\) 在 \\(C\\) 上，\\(25-16=m=9\\)，故 \\(C:x^{2}-y^{2}=9\\)。过 \\(P_{1}\\) 斜率 \\(\\dfrac{1}{2}\\) 的直线 \\(y-4=\\dfrac{1}{2}(x-5)\\) 即 \\(x-2y+3=0\\)，与 \\(x^{2}-y^{2}=9\\) 联立，解得 \\(Q_{1}(-3,0)\\)，故 \\(P_{2}(3,0)\\)，即 \\(x_{2}=3,y_{2}=0\\)。（2）由 \\(P_{n-1}(x_{n-1},y_{n-1})\\)、\\(Q_{n-1}(-x_{n},y_{n})\\) 在斜率为 \\(k\\) 的直线上，得 \\(\\dfrac{y_{n}-y_{n-1}}{-x_{n}-x_{n-1}}=k\\)。又两点均在双曲线上，两式相减得 \\((x_{n}+x_{n-1})(x_{n}-x_{n-1})=(y_{n}+y_{n-1})(y_{n}-y_{n-1})\\)。联立得 \\((1-k)(x_{n}-y_{n})=(1+k)(x_{n-1}-y_{n-1})\\)，即 \\(\\dfrac{x_{n}-y_{n}}{x_{n-1}-y_{n-1}}=\\dfrac{1+k}{1-k}\\)，得证。（3）由（2）\\(x_{n}-y_{n}=\\left(\\dfrac{1+k}{1-k}\\right)^{n-1}\\)，结合 \\(x_{n}^{2}-y_{n}^{2}=9\\) 得 \\(x_{n}+y_{n}=\\dfrac{9}{\\left(\\dfrac{1+k}{1-k}\\right)^{n-1}}\\)，解得 \\(x_{n},y_{n}\\)。计算 \\(S_{n}\\) 为与 \\(n\\) 无关的定值，故 \\(S_{n}=S_{n+1}\\)。"
