 "sol": "(1) \\(f'(x)=3x^{2}-6x-9=3(x^{2}-2x-3)=3(x-3)(x+1)\\)。令 \\(f'(x)>0\\)，得 \\(x<-1\\) 或 \\(x>3\\)；令 \\(f'(x)<0\\)，得 \\(-1<x<3\\)。故递增区间为 \\((-\\infty,-1)\\)、\\((3,+\\infty)\\)，递减区间为 \\((-1,3)\\)。(2) 由 (1) 知 \\(x=-1\\) 为极大值点，极大值 \\(f(-1)=-1-3+9+1=6\\)；\\(x=3\\) 为极小值点，极小值 \\(f(3)=27-27-27+1=-26\\)。"
