 "sol": "(1) \\(z\\) 为实数当且仅当虚部为 0：\\(a^{2}-4=0\\)，解得 \\(a=\\pm2\\)。\n(2) \\(z\\) 为纯虚数当且仅当实部为 0 且虚部不为 0：\\(a^{2}-3a+2=(a-1)(a-2)=0\\)，得 \\(a=1\\) 或 \\(a=2\\)；又 \\(a^{2}-4\\neq0\\) 即 \\(a\\neq\\pm2\\)，故舍去 \\(a=2\\)，得 \\(a=1\\)。\n(3) 第四象限内的点满足：实部大于 0、虚部小于 0。解 \\(a^{2}-3a+2>0\\)，即 \\((a-1)(a-2)>0\\)，得 \\(a<1\\) 或 \\(a>2\\)；解 \\(a^{2}-4<0\\)，得 \\(-2<a<2\\)。取两者交集得 \\(-2<a<1\\)，即 \\(a\\in(-2,1)\\)。"
