 "type": "单选",
 "difficulty": "中",
 "question": "已知集合 \\(A=\\{x|x^2-3x+2=0\\}\\)，\\(B=\\{x|x^2-ax+a-1=0\\}\\)，若 \\(B\\subseteq A\\)，则a的值为（ ）",
