 "difficulty": "难",
 "question": "若命题 \"\\(\\exists x\\in[1,2], x^2-a\\leq0\\)\" 为真命题，则实数a的取值范围是________。",
 "answer": "a≥1",
 "analysis": "存在x∈[1,2]使x²≤a，即a≥x²的最小值。x²在[1,2]上的最小值为1（x=1时），故a≥1。",
 "knowledge": "特称命题为真的条件",
