 "answer": "(1) 全称命题，假（2是素数但不是奇数）；(2) 特称命题，假（判别式Δ=4-12<0）；(3) 全称命题，真",
 "analysis": "(1) 全称命题，2是素数但不是奇数，故为假；<br>(2) 特称命题，x²+2x+3=(x+1)²+2≥2>0，无实根，故为假；<br>(3) 全称命题，绝对值非负，故为真。",
