 "answer": "(1) 0≤a<1；(2) a<0或a≥1",
 "analysis": "(1) p为假，则¬p为真：∀x∈R, ax²+2ax+1>0。<br>①a=0时，1>0恒成立；<br>②a>0时，Δ=4a²-4a<0，解得0<a<1；<br>③a<0时，开口向下，不可能恒大于0。<br>综上：0≤a<1。<br>(2) p为真即存在x使ax²+2ax+1≤0。是(1)的补集：a<0或a≥1。",
 "knowledge": "全称/特称命题的真假转化",
 "tips": "p假→¬p真，转化为恒成立问题；注意a=0的情况"
