 "answer": "(1) f(0)=0；(2) x>0时f(x)=x²-x+1，x=0时f(x)=0，x<0时f(x)=-x²-x-1",
 "analysis": "(1) 奇函数在x=0处有定义，则f(0)=0。<br>(2) 设x<0，则-x>0，f(-x)=(-x)²-(-x)+1=x²+x+1。因为f(x)是奇函数，f(x)=-f(-x)=-x²-x-1。",
