 "analysis": "因为α∈(0,π/2)，β∈(π/2,π)，所以α+β∈(π/2, 3π/2)。又sin(α+β)=3/5>0，所以α+β∈(π/2,π)，cos(α+β)=-4/5。cosβ=-5/13，β∈(π/2,π)，所以sinβ=12/13。sinα = sin[(α+β)-β] = sin(α+β)cosβ - cos(α+β)sinβ = (3/5)(-5/13) - (-4/5)(12/13) = -15/65 + 48/65 = 33/65。",
